/// The token the session cookie carries, for a request with no bearer.
fn cookie_token<'a>(&self, request: &'a RemoteRequest) -> Result<&'a str, RemoteReply> {
    let server_id = self.core.identity().map(|i| i.server_id);
    let token = server_id.and_then(|id| {
        remote::cookie_value(request.cookie.as_deref(), &remote::cookie_name(id))
    });
    let Some(token) = token else {
        return Err(self.refuse(request, 401, "unauthorized", "pair this device first", false));
    };
    self.check_origin(request)?;
    Ok(token)
}

/// A write, or a socket upgrade, from a browser must come from this
/// host's own page: its `Origin` is the `https://` address its `Host`
/// names. A read is not checked.
